 dict(slug='json-validator',action='json-validator',icon='✓',title='JSON Validator',category='Data',desc='Validate JSON syntax and locate errors by line and column.',fields=text('JSON','{"valid":true}'),button='Validate JSON',note='Checks syntax and duplicate keys, not JSON Schema.',how='Uses the same strict parser as JSON Formatter. Objects, arrays, strings, numbers, booleans, and null can all be valid top-level JSON.',faq=('Does valid JSON mean my data is correct?','No. Syntax validation does not check business rules, required fields, or a schema.')),
 dict(slug='base64',action='base64',icon='64',title='Base64 Encoder / Decoder',category='Data',desc='Encode and decode UTF-8 text or binary files with Base64.',fields=select('mode','Conversion',[('encode-text','Text → Base64'),('decode-text','Base64 → text'),('encode-file','File → Base64'),('decode-file','Base64 → file')])+text()+'<div id="file-field" hidden>'+drop()+'</div>',button='Convert',note='Base64 is encoding, not encryption. Decoded files use .bin because the encoding does not contain the original filename.',how='Python base64 performs strict decoding with whitespace allowed. Text is UTF-8; file modes preserve arbitrary bytes.',faq=('Why does text decoding fail for some inputs?','The decoded bytes may be a binary file rather than UTF-8. Choose Base64 → file to download them.')),
 dict(slug='csv-json',action='csv-json',icon='▤',title='CSV ↔ JSON Converter',category='Data',desc='Convert CSV tables to JSON arrays and JSON records to CSV.',fields=select('mode','Direction',[('csv-json','CSV → JSON'),('json-csv','JSON → CSV')])+check('safe_export','Protect spreadsheet export from formula interpretation',True)+text('CSV or JSON','name,age\nJohn,31\nAnna,28'),button='Convert',note='CSV → JSON keeps values as strings. JSON → CSV requires flat objects. Missing/null values become empty fields.',how='Python csv handles quoted commas, quotes, and multiline fields. Headers must be unique and non-empty. JSON columns follow first-seen key order.',faq=('Does safe export change my values?','Yes. It prefixes formula-like cells and headers with an apostrophe. Disable it only when you need exact values and understand how your spreadsheet treats them.')),
 dict(slug='text-cleaner',action='text-cleaner',icon='Aa',title='Text Cleaner',category='Text',desc='Tidy whitespace, blank lines, tabs, and non-printable characters.',fields=text()+''.join(check(k,t,v) for k,t,v in [('extra_spaces','Remove extra spaces',True),('empty_lines','Remove empty lines',True),('trim','Trim lines',True),('tabs','Convert tabs to 4 spaces',False),('normalize_endings','Normalize line endings to LF',False),('non_printable','Remove non-printable characters',False)]),button='Clean text',note='Character counts use Unicode code points. Line endings are preserved unless normalization is selected.',how='Python applies only your selected cleanup operations, preserving line boundaries. Removing non-printable characters keeps tabs and line endings.',faq=('Will this change meaningful whitespace?','It can. Check the options before processing code, poetry, or other text where indentation matters.')),
 dict(slug='remove-duplicate-lines',action='remove-duplicate-lines',icon='≠',title='Duplicate Line Remover',category='Text',desc='Remove repeated lines and see exactly how many were removed.',fields=text()+check('keep_order','Keep original order',True)+check('ignore_case','Ignore case')+check('trim','Trim spaces'),button='Remove duplicates',note='The first occurrence is retained. Without Keep original order, lines are sorted by their comparison key.',how='Python compares complete lines, with optional Unicode case folding and trimming. A trailing newline does not create a phantom line.',faq=('What happens to blank lines?','Blank lines are values too: one is retained. A completely empty input contains zero lines.')),
 dict(slug='text-diff',action='text-diff',icon='±',title='Text Diff',category='Text',desc='Compare two texts and inspect added, removed, and changed lines.',fields=text('Original text')+text('Modified text',key='modified'),button='Compare texts',note='Maximum 200,000 characters and 5,000 lines per input. Changed pairs are included in added/removed totals.',how='Python difflib produces a unified line diff. Missing final newlines are marked explicitly. User content is displayed as text, never interpreted as HTML.',faq=('Can I cancel a long comparison?','Yes. Cancel terminates the Worker and the next operation starts a fresh engine.')),
 dict(slug='timestamp',action='timestamp',icon='◷',title='Timestamp Converter',category='Developer',desc='Convert Unix seconds or milliseconds to dates and back.',fields=select('mode','Direction',[('unix','Unix timestamp → date'),('date','ISO date → Unix timestamp')])+select('unit','Timestamp unit',[('seconds','Seconds'),('milliseconds','Milliseconds')])+text('Timestamp or ISO 8601 date','1729829382'),button='Convert timestamp',note='Dates without a timezone are treated as UTC. Choose seconds or milliseconds explicitly.',how='Python converts against the UTC epoch with microsecond precision. The browser also displays the instant in its local timezone.',faq=('Are negative timestamps supported?','Yes, within years 1–9999. Fractional values are supported up to microsecond precision; the browser local display has millisecond precision.')),
