 dict(slug='jwt-decoder',action='jwt-decoder',icon='JWT',title='JWT Decoder',category='Developer',desc='Inspect JWT headers and payloads locally, without sending the token anywhere.',fields=text('JWT','xxxxx.yyyyy.zzzzz'),button='Decode JWT',note='This tool decodes JWT contents. It does NOT verify the signature.',how='Python decodes base64url header/payload segments and parses strict JSON. Standard date claims are shown as UTC, without validating their authenticity.',faq=('Can I trust the decoded claims?','No. All claims are unverified. This tool does not fetch issuer URLs or keys, authenticate tokens, or support encrypted five-segment JWE.')),
